class node;
class Solution;

class Node {
public:
    int a;
    int b; 
    int c;
    Node(){}
    Node(vector&lt;int&gt; v) {
        sort(v.begin(), v.end());
        a = v[0];       
        b = v[1];       
        c = v[2];       
    }

    bool operator==(Node i) {
        if ( i.a==this-&gt;a &amp;&amp; i.b==this-&gt;b &amp;&amp;i.c==this-&gt;c ) {
            return true;
        } else {
            return false;
        }
