        }

        @Override
        public void onClick(View v) {
            this.v = v;
            mIRecyclerViewClickListener.onItemClick(getAdapterPosition());
        }
    }


}
</code></pre>

Title: How to make an expandable/collapsable section widget in Qt.
Body: <p>I would like to create a custom widget in Qt with the following features:</p>

<ul>
<li>It is a container</li>
<li>It may be populated with any Qt layout</li>
<li>It may be inside any Qt layout</li>
<li>A button allows to collapse/fold vertically the content, so only the button is visible, all the contained layout is invisible.</li>
<li>The previous button allows to expand/unfold it again to the size of the layout content.</li>
<li>The expanding/collapsing is based on sizes (not on show/hide) to allows animation.</li>
<li>Usable in QDesigner</li>
</ul>

<p>To provide an idea, here is an image of a similar widget (not Qt):
<a href="https://i.stack.imgur.com/KsVwP.png" rel="noreferrer"><img src="https://i.stack.imgur.com/KsVwP.png" alt="enter image description here"></a></p>

<p>I already have a frame that work correctly and is exposed in QDesigner. I need now to make it to extend/collapse, which does not seem so simple.</p>

<p>I tried to play with resize(), sizePolicy(), sizeHint() but that does not work:
When the frame is collapsed I got following values:</p>

<pre><code>sizeHint: (500,20)
size    : (500,20)
closestAcceptableSize: (518,150)
Painted size: (518, 150)
</code></pre>

<p>QLayout::closestAcceptableSize is not part of the widget so I cannot change it.</p>

<p><strong>Any hint or/and code snippet to achieve that?</strong></p>

<p>EDITED:
Here a simple example. I removed all except necessary. </p>

<p>main.cpp example</p>

<pre><code>#include &lt;QWidget&gt;
#include &lt;QPushButton&gt;
#include &lt;QVBoxLayout&gt;

#include "section.hpp"


using namespace myWidgets;
int main(int argc, char *argv[])
{
    QApplication a(argc, argv);


    // Create the main Window
    QWidget window;
    window.resize(500,500);
    window.setStyleSheet("QPushButton:{background-color:rgba(128,128,128,192);}");

    // Create the main window layout
    QVBoxLayout topLayout(&amp;window);
    QWidget *w1 = new QWidget();
    w1-&gt;setStyleSheet("background-color:rgba(128,128,128,192);");
    topLayout.addWidget(w1);

    Section section(&amp;window);
    topLayout.addWidget(&amp;section);

    QVBoxLayout inLayout(&amp;section);
    QPushButton *button = new QPushButton();
    button-&gt;setMinimumHeight(100);
    inLayout.addWidget(button);

    QWidget *w2 = new QWidget();
    w2-&gt;setStyleSheet("background-color:rgba(128,128,128,192);");
    topLayout.addWidget(w2);



    window.show();

    return a.exec();
}
</code></pre>

<p>Section.hpp</p>

<pre><code>#ifndef SECTION_HPP
#define SECTION_HPP

#include &lt;QPushButton&gt; //for the expand/collapse button
#include &lt;QtDesigner/QDesignerExportWidget&gt;
#include &lt;QLayout&gt;
#include &lt;QPainter&gt;
#include &lt;QPaintEvent&gt;
#include &lt;QDebug&gt;


// Compatibility for noexcept, not supported in vsc++
#ifdef _MSC_VER
#define noexcept throw()
#endif

#if defined SECTION_BUILD
    #define SECTION_BUILD_DLL_SPEC Q_DECL_EXPORT
#elif defined SECTION_EXEC
    #define SECTION_BUILD_DLL_SPEC
#else
    #define SECTION_BUILD_DLL_SPEC Q_DECL_IMPORT
#endif

namespace myWidgets
{

class SECTION_BUILD_DLL_SPEC Section : public QWidget
{
    Q_OBJECT

    Q_PROPERTY( bool is_expanded MEMBER isExpanded)

public:
    // Constructor, standard
    explicit Section( QWidget *parent=0 ): QWidget(parent),
        expandButton(this)
    {
        expandButton.resize(20,20);
        expandButton.move(0,0);
        expandButton.connect(&amp;expandButton, &amp;QPushButton::clicked,
                             this, &amp;Section::expandCollapseEvent);

        QMargins m= contentsMargins();
        m.setTop(m.top()+25);
        setContentsMargins(m);
        //setSizePolicy(sizePolicy().horizontalPolicy(), QSizePolicy::Minimum);

    }

    virtual void expand( bool expanding ) noexcept
    {
        resize(sizeHint());
        isExpanded = expanding;
        updateGeometry();

qDebug() &lt;&lt; (isExpanded? "expanded":"collapsed") &lt;&lt; sizeHint() &lt;&lt; QWidget::size() &lt;&lt;
            parentWidget()-&gt;layout()-&gt;closestAcceptableSize(this, size());
    }

    virtual QSize sizeHint() const noexcept override
    {
        if (isExpanded) return QSize(layout()-&gt;contentsRect().width(),
                                     layout()-&gt;contentsRect().height());
        else return QSize(layout()-&gt;contentsRect().width(), 20);
    }

    // Implement custom appearance
    virtual void paintEvent(QPaintEvent *e) noexcept override
    {
        (void) e; //TODO: remove
        QPainter p(this);
        p.setClipRect(e-&gt;rect());
        p.setRenderHint(QPainter::Antialiasing );
        p.fillRect(e-&gt;rect(), QColor(0,0,255,128));
    }

protected:

    // on click of the expandButton, collapse/expand this widget
    virtual void expandCollapseEvent() noexcept
    {
        expand(!isExpanded);
    }


    bool isExpanded = true; //whenever the section is collapsed(false) or expanded(true)
    QPushButton expandButton; //the expanding/collapsing button
};

}


#endif // SECTION_HPP
</code></pre>

Title: How to embed Javascript widget that depends on jQuery into an unknown environment.
Body: <p>I'm developing a javascript widget that depends on jQuery.  The widget may or may not be loaded onto a page that already has jQuery loaded.  There are many problems that come up in this case...</p>

<ol>
<li><p>If the web page does not have jQuery, I must load my own jQuery.  There seems to be a delicate timing issue when doing this, however.  For example, if my widget loads and executes before jQuery is finished loading and executing, I get a <code>jQuery is not defined</code> error.</p></li>
<li><p>If the web page does have jQuery, I can usually work with it.  If the jQuery version is old, however, I would like to load my own.  If I do load my own, however, I need to do it in such a way as to not stomp on their <code>$</code> variable.  If I set <code>jQuery.noConflict()</code> and any of their scripts depend on <code>$</code>, then I have just broken their page.</p></li>
<li><p>If the web page uses another javascript library (e.g. prototype), I needed to be sensitive of prototype's <code>$</code> variable also.</p></li>
</ol>

<p>Because of all of the above, it is seeming easier to not depend on jQuery.  But before I go down that road, which will involve mostly rewriting my widget code, I wanted to ask for advice first.</p>

<p>The basic skeleton of my code, including the timing bug and sometimes <code>$</code> bugs, follows:</p>

<pre><code>&lt;script type="text/javascript" charset="utf-8"&gt;
// &lt;![CDATA
 if (typeof jQuery === 'undefined') {
  var head = document.getElementsByTagName('head')[0];
  var script = document.createElement('script');
  script.type = 'text/javascript';
  script.src = '{{ URL }}/jquery.js';
  head.appendChild(script);
 }
// ]]&gt;
&lt;/script&gt;
&lt;script type="text/javascript" src="{{ URL }}/widget.js"&gt;&lt;/script&gt;
</code></pre>

<p>My widget has the following structure:</p>

<pre><code>(function($) {
 var mywidget = {
  init: function() {
   ...
  }
 };
 $(document).ready(function() {
   mywidget.init();
 });
})(jQuery);
</code></pre>

<p>If there are any pointers or resources for achieving a widget that can work in all the mentioned environments, they would be greatly appreciated.</p>

Title: How to implement expandable panels in Android?.
Body: <p>Is there an easy way to create expandable/collapsible blocks like seen in official market app?</p>

<p>Screenshot of Market app, when you click on "More" button, the description section expands with animation:</p>

<p><img src="https://i.stack.imgur.com/0hqno.jpg" alt="enter image description here"></p>

<p>I know of <a href="http://developer.android.com/reference/android/widget/SlidingDrawer.html" rel="noreferrer">SlidingDrawer</a> but it doesn't seem to be suited for stuff like this--it's supposed to be put in overlay, and doesn't support half-open states.</p>

<p><strong>Update:</strong></p>

<p>Here's my half-working solution. It's a custom widget that extends <code>LinearLayout</code>. It kind-of works, but doesn't handle edge cases well, like content height smaller than <code>collapsedHeight</code> parameter. I'm sure with enough staring, digging in code and experimenting the quirks could be fixed. Was hoping to avoid doing that, and save some time by using a ready-made official or 3rd party solution. Anyway, here it is, code:</p>

<pre><code>package com.example.androidapp.widgets;

import android.content.Context;
import android.content.res.TypedArray;
import android.util.AttributeSet;
import android.view.View;
import android.view.animation.Animation;
import android.view.animation.Transformation;
import android.widget.LinearLayout;

import com.example.androidapp.R;

public class ExpandablePanel extends LinearLayout {

    private final int mHandleId;
    private final int mContentId;

    private View mHandle;
    private View mContent;

    private boolean mExpanded = true;
    private int mCollapsedHeight = 0;
    private int mContentHeight = 0;

    public ExpandablePanel(Context context) {
        this(context, null);
    }

    public ExpandablePanel(Context context, AttributeSet attrs) {
        super(context, attrs);

        TypedArray a = context.obtainStyledAttributes(attrs,
            R.styleable.ExpandablePanel, 0, 0);

        // How high the content should be in "collapsed" state
        mCollapsedHeight = (int) a.getDimension(
            R.styleable.ExpandablePanel_collapsedHeight, 0.0f);

        int handleId = a.getResourceId(R.styleable.ExpandablePanel_handle, 0);
        if (handleId == 0) {
            throw new IllegalArgumentException(
                "The handle attribute is required and must refer "
                    + "to a valid child.");
        }

        int contentId = a.getResourceId(R.styleable.ExpandablePanel_content, 0);
        if (contentId == 0) {
            throw new IllegalArgumentException(
                "The content attribute is required and must refer "
                    + "to a valid child.");
        }

        mHandleId = handleId;
        mContentId = contentId;

        a.recycle();
    }

    @Override
    protected void onFinishInflate() {
        super.onFinishInflate();

        mHandle = findViewById(mHandleId);
        if (mHandle == null) {
            throw new IllegalArgumentException(
                "The handle attribute is must refer to an"
                    + " existing child.");
        }

        mContent = findViewById(mContentId);
        if (mContent == null) {
            throw new IllegalArgumentException(
                "The content attribute is must refer to an"
                    + " existing child.");
        }

        mHandle.setOnClickListener(new PanelToggler());
    }

    @Override
    protected void onMeasure(int widthMeasureSpec, int heightMeasureSpec) {
        if (mContentHeight == 0) {
            // First, measure how high content wants to be
            mContent.measure(widthMeasureSpec, MeasureSpec.UNSPECIFIED);
            mContentHeight = mContent.getMeasuredHeight();
        }

        // Then let the usual thing happen
        super.onMeasure(widthMeasureSpec, heightMeasureSpec);
    }

    private class PanelToggler implements OnClickListener {
        public void onClick(View v) {
            Animation a;
            if (mExpanded) {
                a = new ExpandAnimation(mContentHeight, mCollapsedHeight);
            } else {
                a = new ExpandAnimation(mCollapsedHeight, mContentHeight);
            }
            a.setDuration(500);
            mContent.startAnimation(a);
            mExpanded = !mExpanded;
        }
    }

    private class ExpandAnimation extends Animation {
        private final int mStartHeight;
        private final int mDeltaHeight;

        public ExpandAnimation(int startHeight, int endHeight) {
            mStartHeight = startHeight;
            mDeltaHeight = endHeight - startHeight;
        }

        @Override
        protected void applyTransformation(float interpolatedTime,
            Transformation t) {
            android.view.ViewGroup.LayoutParams lp = mContent.getLayoutParams();
            lp.height = (int) (mStartHeight + mDeltaHeight * interpolatedTime);
            mContent.setLayoutParams(lp);
        }

        @Override
        public boolean willChangeBounds() {
            // TODO Auto-generated method stub
            return true;
        }
    }
}
</code></pre>

<p>Here's <code>res/values/attrs.xml</code>:</p>

<pre><code>&lt;?xml version="1.0" encoding="utf-8"?&gt;
&lt;resources&gt;
  &lt;declare-styleable name="ExpandablePanel"&gt;
    &lt;attr name="handle" format="reference" /&gt;
    &lt;attr name="content" format="reference" /&gt;
    &lt;attr name="collapsedHeight" format="dimension" /&gt;
  &lt;/declare-styleable&gt;
&lt;/resources&gt;
</code></pre>

<p>And here's how I use it in layout:</p>

<pre><code>&lt;com.example.androidapp.widgets.ExpandablePanel
    android:orientation="vertical"
    android:layout_height="wrap_content"
    android:layout_width="fill_parent"
    example:handle="@+id/expand"
    example:content="@+id/value"
    example:collapsedHeight="50dip"&gt;
    &lt;TextView
        android:id="@id/value"
        android:layout_width="fill_parent"
        android:layout_height="wrap_content"
        android:maxHeight="50dip"
        /&gt;
    &lt;Button
        android:id="@id/expand"
        android:layout_width="wrap_content"
        android:layout_height="wrap_content"
        android:text="More" /&gt;
&lt;/com.example.androidapp.widgets.ExpandablePanel&gt;
</code></pre>

